35	#ifndef D_VALUE_BASE_H
36	#define D_VALUE_BASE_H
37	
38	#include "common.h"
39	
40	#include <string>
41	#include <deque>
42	#include <map>
43	#include <memory>
44	
45	#include "a2functional.h"
46	
47	namespace aria2 {
48	
49	class ValueBaseVisitor;
50	
51	class ValueBase {
52	public:
53	  virtual ~ValueBase() = default;
54	
55	  virtual void accept(ValueBaseVisitor& visitor) const = 0;
56	};
57	
58	class String;
59	class Integer;
60	class Bool;
61	class Null;
62	class List;
63	class Dict;
64	
65	class ValueBaseVisitor {
66	public:
67	  virtual ~ValueBaseVisitor() = default;
68	  virtual void visit(const String& string) = 0;
69	  virtual void visit(const Integer& integer) = 0;
70	  virtual void visit(const Bool& boolValue) = 0;
71	  virtual void visit(const Null& nullValue) = 0;
72	  virtual void visit(const List& list) = 0;
73	  virtual void visit(const Dict& dict) = 0;
74	};
75	
76	class String : public ValueBase {
77	public:
78	  typedef std::string ValueType;
79	
80	  String(const ValueType& string);
81	  String(ValueType&& string);
82	
83	  explicit String(const char* cstring);
84	
85	  String(const char* data, size_t length);
86	
87	  String(const unsigned char* data, size_t length);
88	
89	  template <typename InputIterator>
90	  String(InputIterator first, InputIterator last) : str_(first, last)
91	  {
92	  }
93	
94	  String();
95	
96	  // Don't allow copying
97	  String(const String&) = delete;
98	  String& operator=(const String&) = delete;
99	
100	  const ValueType& s() const;
101	
102	  ValueType popValue() const;
103	
104	  // Returns std::string.data() cast to unsigned char*.
105	  // Use s().size() to get length.
106	  const unsigned char* uc() const;
107	
108	  static std::unique_ptr<String> g(const ValueType& string);
109	  static std::unique_ptr<String> g(ValueType&& string);
110	
111	  static std::unique_ptr<String> g(const unsigned char* data, size_t length);
112	
113	  template <typename InputIterator>
114	  static std::unique_ptr<String> g(InputIterator first, InputIterator last)
115	  {
116	    return make_unique<String>(first, last);
117	  }
118	
119	  virtual void accept(ValueBaseVisitor& visitor) const CXX11_OVERRIDE;
120	
121	private:
122	  ValueType str_;
123	};
124	
125	class Integer : public ValueBase {
126	public:
127	  typedef int64_t ValueType;
128	
129	  Integer(ValueType integer);
130	
131	  Integer();
132	
133	  // Don't allow copying
134	  Integer(const Integer&) = delete;
135	  Integer& operator=(const Integer&) = delete;
136	
137	  // Returns Integer.
138	  ValueType i() const;
139	
140	  static std::unique_ptr<Integer> g(ValueType integer);
141	
142	  virtual void accept(ValueBaseVisitor& visitor) const CXX11_OVERRIDE;
143	
144	private:
145	  ValueType integer_;
146	};
147	
148	class Bool : public ValueBase {
149	public:
150	  static std::unique_ptr<Bool> gTrue();
151	  static std::unique_ptr<Bool> gFalse();
152	  Bool(bool val);
153	  bool val() const;
154	  virtual void accept(ValueBaseVisitor& visitor) const CXX11_OVERRIDE;
155	
156	private:
157	  // Don't allow copying
158	  Bool(const Bool&) = delete;
159	  Bool& operator=(const Bool&) = delete;
160	  bool val_;
161	};
162	
163	class Null : public ValueBase {
164	public:
165	  static std::unique_ptr<Null> g();
166	  Null();
167	  virtual void accept(ValueBaseVisitor& visitor) const CXX11_OVERRIDE;
168	
169	private:
170	  // Don't allow copying
171	  Null(const Null&);
172	  Null& operator=(const Null&);
173	};
174	
175	class List : public ValueBase {
176	public:
177	  typedef std::deque<std::unique_ptr<ValueBase>> ValueType;
178	
179	  List();
180	
181	  // Don't allow copying
182	  List(const List&) = delete;
183	  List& operator=(const List&) = delete;
184	
185	  // Appends given v to list.
186	  void append(std::unique_ptr<ValueBase> v);
187	
188	  // Appending string is so common that we provide shortcut function.
189	  void append(String::ValueType string);
190	
191	  // Alias for append()
192	  List& operator<<(std::unique_ptr<ValueBase> v);
193	
194	  // Returns the object at given index.
195	  ValueBase* get(size_t index) const;
196	
197	  // Set the object at given index.
198	  void set(size_t index, std::unique_ptr<ValueBase> v);
199	
200	  // Returns the const reference of the object at the given index.
201	  ValueBase* operator[](size_t index) const;
202	
203	  // Pops the value in the front of the list.
204	  void pop_front();
205	
206	  // Pops the value in the back of the list.
207	  void pop_back();
208	
209	  // Returns a read/write iterator that points to the first object in
210	  // list.
211	  ValueType::iterator begin();
212	
213	  // Returns a read/write iterator that points to the one past the
214	  // last object in list.
215	  ValueType::iterator end();
216	
217	  // Returns a read/write read-only iterator that points to the first
218	  // object in list.
219	  ValueType::const_iterator begin() const;
220	
221	  // Returns a read/write read-only iterator that points to the one
222	  // past the last object in list.
223	  ValueType::const_iterator end() const;
224	
225	  // Returns a read/write read-only iterator that points to the first
226	  // object in list.
227	  ValueType::const_iterator cbegin() const;
228	
229	  // Returns a read/write read-only iterator that points to the one
230	  // past the last object in list.
231	  ValueType::const_iterator cend() const;
232	
233	  // Returns size of list.
234	  size_t size() const;
235	
236	  // Returns true if size of list is 0.
237	  bool empty() const;
238	
239	  static std::unique_ptr<List> g();
240	
241	  virtual void accept(ValueBaseVisitor& visitor) const CXX11_OVERRIDE;
242	
243	private:
244	  ValueType list_;
245	};
246	
247	class Dict : public ValueBase {
248	public:
249	  typedef std::map<std::string, std::unique_ptr<ValueBase>> ValueType;
250	
251	  Dict();
252	
253	  // Don't allow copying
254	  Dict(const Dict&) = delete;
255	  Dict& operator=(const Dict&) = delete;
256	
257	  void put(std::string key, std::unique_ptr<ValueBase> vlb);
258	
259	  // Putting string is so common that we provide shortcut function.
260	  void put(std::string key, String::ValueType string);
261	
262	  ValueBase* get(const std::string& key) const;
263	
264	  // Returns the reference to object associated with given key.  If
265	  // the key is not found, nullptr is returned.
266	  ValueBase* operator[](const std::string& key) const;
267	
268	  // Returns true if the given key is found in dict.
269	  bool containsKey(const std::string& key) const;
270	
271	  // Removes specified key from dict.
272	  void removeKey(const std::string& key);
273	
274	  // Removes specified key from dict and return its associated value.
275	  std::unique_ptr<ValueBase> popValue(const std::string& key);
276	
277	  // Returns a read/write iterator that points to the first pair in
278	  // the dict.
279	  ValueType::iterator begin();
280	
281	  // Returns a read/write read-only iterator that points to one past
282	  // the last pair in the dict.
283	  ValueType::iterator end();
284	
285	  // Returns a read/write read-only iterator that points to the first
286	  // pair in the dict.
287	  ValueType::const_iterator begin() const;
288	
289	  // Returns a read/write read-only iterator that points to one past
290	  // the last pair in the dict.
291	  ValueType::const_iterator end() const;
292	
293	  // Returns a read/write read-only iterator that points to the first
294	  // pair in the dict.
295	  ValueType::const_iterator cbegin() const;
296	
297	  // Returns a read/write read-only iterator that points to one past
298	  // the last pair in the dict.
299	  ValueType::const_iterator cend() const;
300	
301	  // Returns size of Dict.
302	  size_t size() const;
303	
304	  // Returns true if size of Dict is 0.
305	  bool empty() const;
306	
307	  static std::unique_ptr<Dict> g();
308	
309	  virtual void accept(ValueBaseVisitor& visitor) const CXX11_OVERRIDE;
310	
311	private:
312	  ValueType dict_;
313	};
314	
315	class EmptyDowncastValueBaseVisitor : public ValueBaseVisitor {
316	public:
317	  EmptyDowncastValueBaseVisitor() {}
318	  virtual void visit(const String& v) CXX11_OVERRIDE {}
319	  virtual void visit(const Integer& v) CXX11_OVERRIDE {}
320	  virtual void visit(const Bool& v) CXX11_OVERRIDE {}
321	  virtual void visit(const Null& v) CXX11_OVERRIDE {}
322	  virtual void visit(const List& v) CXX11_OVERRIDE {}
323	  virtual void visit(const Dict& v) CXX11_OVERRIDE {}
324	};
325	
326	template <typename T>
327	class DowncastValueBaseVisitor : public EmptyDowncastValueBaseVisitor {
328	public:
329	  DowncastValueBaseVisitor() : result_{nullptr} {}
330	
331	  virtual void visit(const T& t) { result_ = &t; }
332	
333	  const T* getResult() const { return result_; }
334	
335	  void setResult(const T* r) { result_ = r; }
336	
337	private:
338	  const T* result_;
339	};
340	
341	template <typename T, typename VPtr> T* downcast(const VPtr& v)
342	{
343	  if (v) {
344	    DowncastValueBaseVisitor<T> visitor;
345	    v->accept(visitor);
346	    return const_cast<T*>(visitor.getResult());
347	  }
348	  else {
349	    return 0;
350	  }
351	}
352	
353	} // namespace aria2
354	
355	#endif // D_VALUE_BASE_H
356

