63	public:
64	  JsonParser(StructParserStateMachine* psm);
65	  ~JsonParser();
66	  // Parses |size| bytes of data |data| and returns the number of
67	  // bytes processed. On error, one of the negative error codes is
68	  // returned.
69	  ssize_t parseUpdate(const char* data, size_t size);
70	  // Parses |size| bytes of data |data| and returns the number of
71	  // bytes processed. On error, one of the negative error codes is
72	  // returned. Call this function to signal the parser that this is
73	  // the last piece of data. This function does NOT reset the internal
74	  // state.
75	  ssize_t parseFinal(const char* data, size_t size);
76	  // Resets the internal state of the parser and makes it ready for
77	  // reuse.
78	  void reset();
79	
80	private:
81	  int pushState(int state);
82	  int stateTop() const;
83	  int popState();
84	  void runBeginCallback(int elementType);
85	  void runEndCallback(int elementType);
86	  void runCharactersCallback(const char* data, size_t len);
87	  void runNumberCallback(int64_t number, int frac, int exp);
88	  void runBoolCallback(bool bval);
89	
90	  void onStringEnd();
91	  void onNumberEnd();
92	  void onObjectEnd();
93	  void onArrayEnd();
94	  void onValueEnd();
95	  void onBoolEnd();
96	  void onNullEnd();
97	
98	  void consumeUnicode(char c);
99	  int consumeLowSurrogate(char c);
100	
101	  StructParserStateMachine* psm_;
102	  std::stack<int> stateStack_;
103	  int currentState_;
104	  // Unicode codepoint
105	  uint16_t codepoint_;
106	  // For low-surrogate codepoint
107	  uint16_t codepoint2_;
108	  int numberSign_;
109	  int64_t number_;
110	  int frac_;
111	  int expSign_;
112	  int exp_;
113	  size_t numConsumed_;
114	  int lastError_;
115	};
