44	void ValueValueBaseStructParserState::beginElement(
45	    ValueBaseStructParserStateMachine* psm, int elementType)
46	{
47	  switch (elementType) {
48	  case STRUCT_DICT_T:
49	    psm->setCurrentFrameValue(Dict::g());
50	    psm->pushDictState();
51	    break;
52	  case STRUCT_ARRAY_T:
53	    psm->setCurrentFrameValue(List::g());
54	    psm->pushArrayState();
55	    break;
56	  case STRUCT_STRING_T:
57	    psm->pushStringState();
58	    break;
59	  case STRUCT_NUMBER_T:
60	    psm->pushNumberState();
61	    break;
62	  case STRUCT_BOOL_T:
63	    psm->pushBoolState();
64	    break;
65	  case STRUCT_NULL_T:
66	    psm->pushNullState();
67	    break;
68	  default:
69	    // Not reachable
70	    assert(0);
71	  }
72	}
73	
74	void DictValueBaseStructParserState::beginElement(
75	    ValueBaseStructParserStateMachine* psm, int elementType)
76	{
77	  switch (elementType) {
78	  case STRUCT_DICT_KEY_T:
79	    psm->pushFrame();
80	    psm->pushDictKeyState();
81	    break;
82	  case STRUCT_DICT_DATA_T:
83	    psm->pushDictDataState();
84	    break;
85	  default:
86	    // Not reachable
87	    assert(0);
88	  }
89	}
