91	void DictKeyValueBaseStructParserState::endElement(
92	    ValueBaseStructParserStateMachine* psm, int elementType)
93	{
94	  psm->setCurrentFrameName(psm->getCharacters());
95	}
96	
97	void DictDataValueBaseStructParserState::endElement(
98	    ValueBaseStructParserStateMachine* psm, int elementType)
99	{
100	  psm->popDictFrame();
101	}
102	
103	void ArrayValueBaseStructParserState::beginElement(
104	    ValueBaseStructParserStateMachine* psm, int elementType)
105	{
106	  assert(elementType == STRUCT_ARRAY_DATA_T);
107	  psm->pushFrame();
108	  psm->pushArrayDataState();
109	}
110	
111	void ArrayDataValueBaseStructParserState::endElement(
112	    ValueBaseStructParserStateMachine* psm, int elementType)
113	{
114	  psm->popArrayFrame();
115	}
116	
117	void StringValueBaseStructParserState::endElement(
118	    ValueBaseStructParserStateMachine* psm, int elementType)
119	{
120	  psm->setCurrentFrameValue(String::g(psm->getCharacters()));
