47	enum {
48	  JSON_FINISH,
49	  JSON_ERROR,
50	  JSON_VALUE,
51	  JSON_OBJECT_KEY,
52	  JSON_OBJECT_VAL,
53	  JSON_OBJECT_SEP,
54	  JSON_ARRAY,
55	  JSON_ARRAY_SEP,
56	  JSON_STRING,
