517	ssize_t JsonParser::parseFinal(const char* data, size_t len)
518	{
519	  ssize_t rv;
520	  rv = parseUpdate(data, len);
521	  if (rv >= 0) {
522	    if (currentState_ != JSON_FINISH) {
523	      rv = ERR_PREMATURE_DATA;
524	    }
525	  }
526	  return rv;
527	}
