529	void JsonParser::reset()
530	{
531	  psm_->reset();
532	  currentState_ = JSON_VALUE;
533	  lastError_ = 0;
534	  while (!stateStack_.empty()) {
535	    stateStack_.pop();
536	  }
537	  stateStack_.push(JSON_FINISH);
538	}
