540	void JsonParser::onStringEnd()
541	{
542	  runEndCallback(stateTop() == JSON_OBJECT_KEY ? STRUCT_DICT_KEY_T
543	                                               : STRUCT_STRING_T);
544	  onValueEnd();
545	}
