547	void JsonParser::onNumberEnd()
548	{
549	  runNumberCallback(numberSign_ * number_, frac_, expSign_ * exp_);
550	  runEndCallback(STRUCT_NUMBER_T);
551	  onValueEnd();
552	}
553	
554	void JsonParser::onObjectEnd()
555	{
556	  runEndCallback(STRUCT_DICT_T);
557	  onValueEnd();
558	}
559	
560	void JsonParser::onArrayEnd()
561	{
562	  runEndCallback(STRUCT_ARRAY_T);
563	  onValueEnd();
564	}
565	
566	void JsonParser::onBoolEnd()
567	{
568	  runEndCallback(STRUCT_BOOL_T);
569	  onValueEnd();
570	}
571	
572	void JsonParser::onNullEnd()
573	{
574	  runEndCallback(STRUCT_NULL_T);
575	  onValueEnd();
576	}
577	
578	void JsonParser::onValueEnd()
579	{
580	  switch (stateTop()) {
581	  case JSON_OBJECT_KEY:
582	    popState();
583	    currentState_ = JSON_OBJECT_VAL;
584	    break;
585	  case JSON_OBJECT_VAL:
586	    runEndCallback(STRUCT_DICT_DATA_T);
587	    popState();
588	    currentState_ = JSON_OBJECT_SEP;
589	    break;
590	  case JSON_ARRAY:
591	    runEndCallback(STRUCT_ARRAY_DATA_T);
592	    popState();
593	    currentState_ = JSON_ARRAY_SEP;
594	    break;
595	  default:
596	    assert(stateTop() == JSON_FINISH);
597	    currentState_ = stateTop();
598	    break;
599	  }
600	}
