602	int JsonParser::pushState(int state)
603	{
604	  if (stateStack_.size() >= 50) {
605	    return ERR_STRUCTURE_TOO_DEEP;
606	  }
607	  else {
608	    stateStack_.push(state);
609	    return 0;
610	  }
611	}
