613	int JsonParser::stateTop() const { return stateStack_.top(); }
614	
615	int JsonParser::popState()
616	{
617	  int state = stateStack_.top();
618	  stateStack_.pop();
619	  return state;
620	}
621	
622	void JsonParser::consumeUnicode(char c)
623	{
624	  codepoint_ *= 16;
625	  codepoint_ += util::hexCharToUInt(c);
626	  ++numConsumed_;
627	  if (numConsumed_ == 4) {
628	    if (in(codepoint_, 0xD800u, 0xDBFFu)) {
629	      // This is high-surrogate codepoint
630	      currentState_ = JSON_STRING_LOW_SURROGATE_ESCAPE;
631	    }
632	    else {
633	      char temp[3];
634	      size_t len;
635	      if (codepoint_ <= 0x007fu) {
636	        temp[0] = static_cast<char>(codepoint_);
637	        len = 1;
638	      }
639	      else if (codepoint_ <= 0x07ffu) {
640	        temp[0] = 0xC0u | (codepoint_ >> 6);
641	        temp[1] = 0x80u | (codepoint_ & 0x003fu);
642	        len = 2;
643	      }
644	      else {
645	        temp[0] = 0xE0u | (codepoint_ >> 12);
646	        temp[1] = 0x80u | ((codepoint_ >> 6) & 0x003Fu);
647	        temp[2] = 0x80u | (codepoint_ & 0x003Fu);
648	        len = 3;
649	      }
650	      runCharactersCallback(temp, len);
651	      currentState_ = JSON_STRING;
652	    }
653	  }
654	}
655	
656	int JsonParser::consumeLowSurrogate(char c)
657	{
658	  codepoint2_ *= 16;
659	  codepoint2_ += util::hexCharToUInt(c);
660	  ++numConsumed_;
661	  if (numConsumed_ == 4) {
662	    if (!in(codepoint2_, 0xDC00u, 0xDFFFu)) {
663	      return ERR_INVALID_UNICODE_POINT;
664	    }
665	    uint32_t fullcodepoint = 0x010000u;
666	    fullcodepoint += (codepoint_ & 0x03FFu) << 10;
667	    fullcodepoint += (codepoint2_ & 0x03FFu);
