46	namespace {
47	enum {
48	  JSON_FINISH,
49	  JSON_ERROR,
50	  JSON_VALUE,
51	  JSON_OBJECT_KEY,
52	  JSON_OBJECT_VAL,
53	  JSON_OBJECT_SEP,
54	  JSON_ARRAY,
55	  JSON_ARRAY_SEP,
56	  JSON_STRING,
57	  JSON_STRING_ESCAPE,
58	  JSON_STRING_UNICODE,
59	  JSON_STRING_LOW_SURROGATE_ESCAPE,
60	  JSON_STRING_LOW_SURROGATE_U,
61	  JSON_STRING_LOW_SURROGATE,
62	  JSON_NUMBER,
63	  JSON_NUMBER_FRAC,
64	  JSON_NUMBER_EXP_SIGN,
65	  JSON_NUMBER_EXP,
66	  JSON_TRUE,
67	  JSON_FALSE,
68	  JSON_NULL
69	};
70	} // namespace
71	
72	namespace {
73	const char JSON_TRUE_STR[] = "true";
74	const char JSON_FALSE_STR[] = "false";
75	const char JSON_NULL_STR[] = "null";
76	} // namespace
77	
78	JsonParser::JsonParser(StructParserStateMachine* psm)
79	    : psm_(psm),
80	      currentState_(JSON_VALUE),
81	      codepoint_(0),
82	      codepoint2_(0),
83	      numberSign_(1),
84	      number_(0),
85	      frac_(0),
86	      expSign_(1),
87	      exp_(0),
88	      numConsumed_(0),
89	      lastError_(0)
90	{
91	  stateStack_.push(JSON_FINISH);
92	}
