96	namespace {
97	bool isSpace(char c) { return util::isLws(c) || util::isCRLF(c); }
98	} // namespace
99	
100	ssize_t JsonParser::parseUpdate(const char* data, size_t size)
101	{
102	  size_t i;
103	  if (currentState_ == JSON_FINISH) {
104	    return 0;
105	  }
106	  else if (currentState_ == JSON_ERROR) {
107	    return lastError_;
108	  }
109	  for (i = 0; i < size && currentState_ != JSON_FINISH; ++i) {
110	    char c = data[i];
111	    switch (currentState_) {
112	    case JSON_ARRAY:
113	      if (c == ']') {
114	        onArrayEnd();
115	        break;
116	      }
117	      else if (isSpace(c)) {
118	        break;
119	      }
120	      else {
121	        int rv = pushState(currentState_);
122	        if (rv < 0) {
123	          return rv;
124	        }
125	        currentState_ = JSON_VALUE;
126	        runBeginCallback(STRUCT_ARRAY_DATA_T);
127	      }
128	    // Fall through
129	    case JSON_VALUE:
130	      switch (c) {
131	      case '{':
132	        currentState_ = JSON_OBJECT_KEY;
133	        runBeginCallback(STRUCT_DICT_T);
134	        break;
135	      case '[':
136	        currentState_ = JSON_ARRAY;
137	        runBeginCallback(STRUCT_ARRAY_T);
138	        break;
139	      case '"':
140	        currentState_ = JSON_STRING;
141	        runBeginCallback(STRUCT_STRING_T);
142	        break;
143	      case '-':
144	        number_ = 0;
145	        numberSign_ = -1;
146	        numConsumed_ = 0;
147	        currentState_ = JSON_NUMBER;
148	        runBeginCallback(STRUCT_NUMBER_T);
149	        break;
150	      case 't':
151	        numConsumed_ = 1;
152	        currentState_ = JSON_TRUE;
153	        runBeginCallback(STRUCT_BOOL_T);
154	        break;
155	      case 'f':
156	        numConsumed_ = 1;
157	        currentState_ = JSON_FALSE;
158	        runBeginCallback(STRUCT_BOOL_T);
159	        break;
160	      case 'n':
161	        numConsumed_ = 1;
162	        currentState_ = JSON_NULL;
163	        runBeginCallback(STRUCT_NULL_T);
164	        break;
165	      default:
166	        if (util::isDigit(c)) {
167	          number_ = c - '0';
168	          numberSign_ = 1;
169	          numConsumed_ = 1;
170	          currentState_ = JSON_NUMBER;
171	          runBeginCallback(STRUCT_NUMBER_T);
172	        }
173	        else if (!isSpace(c)) {
174	          currentState_ = JSON_ERROR;
175	          return lastError_ = ERR_UNEXPECTED_CHAR_BEFORE_VAL;
176	        }
177	      }
178	      break;
179	    case JSON_TRUE:
180	      if (JSON_TRUE_STR[numConsumed_] == c) {
181	        ++numConsumed_;
182	        if (numConsumed_ == sizeof(JSON_TRUE_STR) - 1) {
183	          runBoolCallback(true);
184	          onBoolEnd();
185	        }
186	      }
187	      else {
188	        currentState_ = JSON_ERROR;
189	        return lastError_ = ERR_UNEXPECTED_LITERAL;
190	      }
191	      break;
192	    case JSON_FALSE:
193	      if (JSON_FALSE_STR[numConsumed_] == c) {
194	        ++numConsumed_;
195	        if (numConsumed_ == sizeof(JSON_FALSE_STR) - 1) {
196	          runBoolCallback(false);
197	          onBoolEnd();
198	        }
199	      }
200	      else {
201	        currentState_ = JSON_ERROR;
202	        return lastError_ = ERR_UNEXPECTED_LITERAL;
203	      }
204	      break;
205	    case JSON_NULL:
206	      if (JSON_NULL_STR[numConsumed_] == c) {
207	        ++numConsumed_;
208	        if (numConsumed_ == sizeof(JSON_NULL_STR) - 1) {
209	          onNullEnd();
210	        }
211	      }
212	      else {
213	        currentState_ = JSON_ERROR;
214	        return lastError_ = ERR_UNEXPECTED_LITERAL;
215	      }
216	      break;
217	    case JSON_OBJECT_KEY:
218	      switch (c) {
219	      case '"': {
220	        int rv = pushState(currentState_);
221	        if (rv < 0) {
222	          return rv;
223	        }
224	        currentState_ = JSON_STRING;
225	        runBeginCallback(STRUCT_DICT_KEY_T);
226	        break;
227	      }
228	      case '}':
229	        onObjectEnd();
230	        break;
231	      default:
232	        if (!isSpace(c)) {
233	          currentState_ = JSON_ERROR;
234	          return lastError_ = ERR_UNEXPECTED_CHAR_BEFORE_OBJ_KEY;
235	        }
236	      }
237	      break;
238	
239	    case JSON_OBJECT_VAL:
240	      switch (c) {
241	      case ':':
242	        pushState(currentState_);
243	        currentState_ = JSON_VALUE;
244	        runBeginCallback(STRUCT_DICT_DATA_T);
245	        break;
246	      default:
247	        if (!isSpace(c)) {
248	          currentState_ = JSON_ERROR;
249	          return lastError_ = ERR_UNEXPECTED_CHAR_BEFORE_OBJ_VAL;
250	        }
251	      }
252	      break;
253	    case JSON_OBJECT_SEP:
254	      switch (c) {
255	      case ',':
256	        currentState_ = JSON_OBJECT_KEY;
257	        break;
258	      case '}':
259	        onObjectEnd();
260	        break;
261	      default:
262	        if (!isSpace(c)) {
263	          currentState_ = JSON_ERROR;
264	          return lastError_ = ERR_UNEXPECTED_CHAR_BEFORE_OBJ_SEP;
265	        }
266	      }
267	      break;
268	    case JSON_ARRAY_SEP:
269	      switch (c) {
270	      case ',':
271	        pushState(JSON_ARRAY);
272	        currentState_ = JSON_VALUE;
273	        runBeginCallback(STRUCT_ARRAY_DATA_T);
274	        break;
275	      case ']':
276	        onArrayEnd();
277	        break;
278	      default:
279	        if (!isSpace(c)) {
280	          currentState_ = JSON_ERROR;
281	          return lastError_ = ERR_UNEXPECTED_CHAR_BEFORE_ARRAY_SEP;
282	        }
283	      }
284	      break;
285	    case JSON_STRING:
286	      switch (c) {
287	      case '"':
288	        onStringEnd();
289	        break;
290	      case '\\':
291	        currentState_ = JSON_STRING_ESCAPE;
292	        break;
293	      default: {
294	        size_t j;
295	        for (j = i; j < size && data[j] != '\\' && data[j] != '"'; ++j)
296	          ;
297	        if (j - i >= 1) {
298	          runCharactersCallback(&data[i], j - i);
299	        }
300	        i = j - 1;
301	        break;
302	      }
303	      }
304	      break;
305	    case JSON_STRING_ESCAPE:
306	      switch (c) {
307	      case 'u':
308	        codepoint_ = 0;
309	        numConsumed_ = 0;
310	        currentState_ = JSON_STRING_UNICODE;
311	        break;
312	      default:
313	        switch (c) {
314	        case 'b':
315	          runCharactersCallback("\b", 1);
316	          break;
317	        case 'f':
318	          runCharactersCallback("\f", 1);
319	          break;
320	        case 'n':
321	          runCharactersCallback("\n", 1);
322	          break;
323	        case 'r':
324	          runCharactersCallback("\r", 1);
325	          break;
326	        case 't':
327	          runCharactersCallback("\t", 1);
328	          break;
329	        default: {
330	          char temp[1];
331	          temp[0] = c;
332	          runCharactersCallback(temp, 1);
333	          break;
334	        }
335	        }
336	        currentState_ = JSON_STRING;
337	      }
338	      break;
339	    case JSON_STRING_UNICODE: {
340	      size_t j;
341	      for (j = i; j < size && currentState_ == JSON_STRING_UNICODE; ++j) {
342	        if (util::isHexDigit(data[j])) {
343	          consumeUnicode(data[j]);
344	        }
345	        else {
346	          currentState_ = JSON_ERROR;
347	          return lastError_ = ERR_INVALID_UNICODE_POINT;
348	        }
349	      }
350	      i = j - 1;
351	      break;
352	    }
353	    case JSON_STRING_LOW_SURROGATE_ESCAPE:
354	      switch (c) {
355	      case '\\':
356	        currentState_ = JSON_STRING_LOW_SURROGATE_U;
357	        break;
358	      default:
359	        currentState_ = JSON_ERROR;
360	        return lastError_ = ERR_INVALID_UNICODE_POINT;
361	      }
362	      break;
363	    case JSON_STRING_LOW_SURROGATE_U:
364	      switch (c) {
365	      case 'u':
366	        codepoint2_ = 0;
367	        numConsumed_ = 0;
368	        currentState_ = JSON_STRING_LOW_SURROGATE;
369	        break;
370	      default:
371	        currentState_ = JSON_ERROR;
372	        return lastError_ = ERR_INVALID_UNICODE_POINT;
373	      }
374	      break;
375	    case JSON_STRING_LOW_SURROGATE: {
376	      size_t j;
377	      for (j = i; j < size && currentState_ == JSON_STRING_LOW_SURROGATE; ++j) {
378	        if (util::isHexDigit(data[j])) {
379	          int rv = consumeLowSurrogate(data[j]);
380	          if (rv != 0) {
381	            currentState_ = JSON_ERROR;
382	            lastError_ = rv;
383	            return rv;
384	          }
385	        }
386	        else {
387	          currentState_ = JSON_ERROR;
388	          return lastError_ = ERR_INVALID_UNICODE_POINT;
389	        }
390	      }
391	      i = j - 1;
392	      break;
393	    }
394	    case JSON_NUMBER: {
395	      size_t j;
396	      for (j = i; j < size && in(data[j], '0', '9'); ++j) {
397	        if ((INT64_MAX - (data[j] - '0')) / 10 < number_) {
398	          currentState_ = JSON_ERROR;
399	          return lastError_ = ERR_NUMBER_OUT_OF_RANGE;
400	        }
401	        number_ *= 10;
402	        number_ += data[j] - '0';
403	      }
404	      numConsumed_ += j - i;
405	      if (j != size) {
406	        if (numConsumed_ == 0) {
407	          currentState_ = JSON_ERROR;
408	          return lastError_ = ERR_INVALID_NUMBER;
409	        }
410	        switch (data[j]) {
411	        case '.':
412	          frac_ = 0;
413	          numConsumed_ = 0;
414	          currentState_ = JSON_NUMBER_FRAC;
415	          i = j;
416	          break;
417	        case 'e':
418	        case 'E':
419	          expSign_ = 1;
420	          exp_ = 0;
421	          numConsumed_ = 0;
422	          currentState_ = JSON_NUMBER_EXP_SIGN;
423	          i = j;
424	          break;
425	        default:
426	          onNumberEnd();
427	          i = j - 1;
428	        }
429	      }
430	      else {
431	        i = j - 1;
432	      }
433	      break;
434	    }
435	    case JSON_NUMBER_FRAC: {
436	      size_t j;
437	      for (j = i; j < size && in(data[j], '0', '9'); ++j) {
438	        // Take into account at most 8 digits
439	        if (frac_ < 100000000) {
440	          frac_ *= 10;
441	          frac_ += data[j] - '0';
442	        }
443	      }
444	      numConsumed_ += j - i;
445	      if (j != size) {
446	        if (numConsumed_ == 0) {
447	          currentState_ = JSON_ERROR;
448	          return lastError_ = ERR_INVALID_NUMBER;
449	        }
450	        switch (data[j]) {
451	        case 'e':
452	        case 'E':
453	          exp_ = 0;
454	          numConsumed_ = 0;
455	          currentState_ = JSON_NUMBER_EXP_SIGN;
456	          i = j;
457	          break;
458	        default:
459	          i = j - 1;
460	          onNumberEnd();
461	        }
462	      }
463	      else {
464	        i = j - 1;
465	      }
466	      break;
467	    }
468	    case JSON_NUMBER_EXP_SIGN:
469	      switch (c) {
470	      case '+':
471	        currentState_ = JSON_NUMBER_EXP;
472	        break;
473	      case '-':
474	        expSign_ = -1;
475	        currentState_ = JSON_NUMBER_EXP;
476	        break;
477	      default:
478	        break;
479	      }
480	      if (currentState_ == JSON_NUMBER_EXP) {
481	        break;
482	      }
483	      else {
484	        currentState_ = JSON_NUMBER_EXP;
485	        // Fall through
486	      }
487	    case JSON_NUMBER_EXP: {
488	      size_t j;
489	      for (j = i; j < size && in(data[j], '0', '9'); ++j) {
490	        // Take into account at most 8 digits
491	        exp_ *= 10;
492	        exp_ += data[j] - '0';
493	        if (exp_ > 18) {
494	          currentState_ = JSON_ERROR;
495	          return lastError_ = ERR_NUMBER_OUT_OF_RANGE;
496	        }
497	      }
498	      numConsumed_ += j - i;
499	      if (j != size) {
500	        if (numConsumed_ == 0) {
501	          currentState_ = JSON_ERROR;
502	          return lastError_ = ERR_INVALID_NUMBER;
503	        }
504	        switch (data[j]) {
505	        default:
506	          onNumberEnd();
507	        }
508	      }
509	      i = j - 1;
510	      break;
511	    }
512	    }
513	  }
514	  return i;
515	}
516	
517	ssize_t JsonParser::parseFinal(const char* data, size_t len)
518	{
519	  ssize_t rv;
520	  rv = parseUpdate(data, len);
521	  if (rv >= 0) {
522	    if (currentState_ != JSON_FINISH) {
523	      rv = ERR_PREMATURE_DATA;
524	    }
525	  }
526	  return rv;
527	}
528	
529	void JsonParser::reset()
530	{
531	  psm_->reset();
532	  currentState_ = JSON_VALUE;
533	  lastError_ = 0;
534	  while (!stateStack_.empty()) {
535	    stateStack_.pop();
536	  }
537	  stateStack_.push(JSON_FINISH);
538	}
539	
540	void JsonParser::onStringEnd()
541	{
542	  runEndCallback(stateTop() == JSON_OBJECT_KEY ? STRUCT_DICT_KEY_T
543	                                               : STRUCT_STRING_T);
544	  onValueEnd();
545	}
546	
547	void JsonParser::onNumberEnd()
548	{
549	  runNumberCallback(numberSign_ * number_, frac_, expSign_ * exp_);
550	  runEndCallback(STRUCT_NUMBER_T);
551	  onValueEnd();
552	}
553	
554	void JsonParser::onObjectEnd()
555	{
556	  runEndCallback(STRUCT_DICT_T);
557	  onValueEnd();
558	}
559	
560	void JsonParser::onArrayEnd()
561	{
562	  runEndCallback(STRUCT_ARRAY_T);
563	  onValueEnd();
564	}
565	
566	void JsonParser::onBoolEnd()
567	{
568	  runEndCallback(STRUCT_BOOL_T);
569	  onValueEnd();
570	}
571	
572	void JsonParser::onNullEnd()
573	{
574	  runEndCallback(STRUCT_NULL_T);
575	  onValueEnd();
576	}
577	
578	void JsonParser::onValueEnd()
579	{
580	  switch (stateTop()) {
581	  case JSON_OBJECT_KEY:
582	    popState();
583	    currentState_ = JSON_OBJECT_VAL;
584	    break;
585	  case JSON_OBJECT_VAL:
586	    runEndCallback(STRUCT_DICT_DATA_T);
587	    popState();
588	    currentState_ = JSON_OBJECT_SEP;
589	    break;
590	  case JSON_ARRAY:
591	    runEndCallback(STRUCT_ARRAY_DATA_T);
592	    popState();
593	    currentState_ = JSON_ARRAY_SEP;
594	    break;
595	  default:
596	    assert(stateTop() == JSON_FINISH);
597	    currentState_ = stateTop();
598	    break;
599	  }
600	}
601	
602	int JsonParser::pushState(int state)
603	{
604	  if (stateStack_.size() >= 50) {
605	    return ERR_STRUCTURE_TOO_DEEP;
606	  }
607	  else {
608	    stateStack_.push(state);
609	    return 0;
610	  }
611	}
612	
613	int JsonParser::stateTop() const { return stateStack_.top(); }
614	
615	int JsonParser::popState()
616	{
617	  int state = stateStack_.top();
618	  stateStack_.pop();
619	  return state;
620	}
621	
622	void JsonParser::consumeUnicode(char c)
623	{
624	  codepoint_ *= 16;
625	  codepoint_ += util::hexCharToUInt(c);
626	  ++numConsumed_;
627	  if (numConsumed_ == 4) {
628	    if (in(codepoint_, 0xD800u, 0xDBFFu)) {
629	      // This is high-surrogate codepoint
630	      currentState_ = JSON_STRING_LOW_SURROGATE_ESCAPE;
631	    }
632	    else {
633	      char temp[3];
634	      size_t len;
635	      if (codepoint_ <= 0x007fu) {
636	        temp[0] = static_cast<char>(codepoint_);
637	        len = 1;
638	      }
639	      else if (codepoint_ <= 0x07ffu) {
640	        temp[0] = 0xC0u | (codepoint_ >> 6);
641	        temp[1] = 0x80u | (codepoint_ & 0x003fu);
642	        len = 2;
643	      }
644	      else {
645	        temp[0] = 0xE0u | (codepoint_ >> 12);
646	        temp[1] = 0x80u | ((codepoint_ >> 6) & 0x003Fu);
647	        temp[2] = 0x80u | (codepoint_ & 0x003Fu);
648	        len = 3;
649	      }
650	      runCharactersCallback(temp, len);
651	      currentState_ = JSON_STRING;
652	    }
653	  }
654	}
655	
656	int JsonParser::consumeLowSurrogate(char c)
657	{
658	  codepoint2_ *= 16;
659	  codepoint2_ += util::hexCharToUInt(c);
660	  ++numConsumed_;
661	  if (numConsumed_ == 4) {
662	    if (!in(codepoint2_, 0xDC00u, 0xDFFFu)) {
663	      return ERR_INVALID_UNICODE_POINT;
664	    }
665	    uint32_t fullcodepoint = 0x010000u;
666	    fullcodepoint += (codepoint_ & 0x03FFu) << 10;
667	    fullcodepoint += (codepoint2_ & 0x03FFu);
668	    char temp[4];
669	    temp[0] = 0xf0u | (fullcodepoint >> 18);
670	    temp[1] = 0x80u | ((fullcodepoint >> 12) & 0x003Fu);
671	    temp[2] = 0x80u | ((fullcodepoint >> 6) & 0x003Fu);
672	    temp[3] = 0x80u | (fullcodepoint & 0x003Fu);
673	    runCharactersCallback(temp, sizeof(temp));
674	    currentState_ = JSON_STRING;
675	  }
676	  return 0;
677	}
